writing.exampleCode:
fn prefix(text: &str, n: usize) -> String {
    text.chars().take(n).collect()
}
fn main() {
    assert_eq!(prefix("É🦀rust", 2), "É🦀");
    assert_eq!(prefix("abc", 0), "");
}

